INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Common threats like car and industrial accidents get reported only when unusual. Rare threats like product tampering get reported every time. People judge risk by how often a threat comes to their attention.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer by chaining the last sentence to the first two. Rare threats show up in the news every time; common threats mostly don't. People judge risk by how often they hear about a threat. So people who get their information from the news will see rare threats as bigger, compared with common ones, than they really are.$batch08$), (2, $batch08$Goal$batch08$, $batch08$News-reliant people overestimate rare threats relative to common ones.$batch08$)) v(position,label,body) WHERE e.id=$batch08$cc38882a-af24-4ead-b93e-54588e58eeca$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
